CREATE DEFINER=`root`@`localhost` PROCEDURE `calcular_valor_estoque`(IN p_id_produto INT)
BEGIN
    DECLARE v_nome VARCHAR(40);
    DECLARE v_preco DECIMAL(10,2);
    DECLARE v_estoque INT;
    DECLARE v_valor_total DECIMAL(10,2);

    SELECT 
        nome,
        preco,
        qtd_estoque,
        (preco * qtd_estoque)
    INTO 
        v_nome,
        v_preco,
        v_estoque,
        v_valor_total
    FROM produto
    WHERE id_produto = p_id_produto;

    SELECT 
        v_nome        AS nome_produto,
        v_preco       AS preco,
        v_estoque     AS quantidade_estoque,
        v_valor_total AS valor_total_estoque;
END ;;
DELIMITER ;
