DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `listar_produtos_cursor`()
BEGIN
    DECLARE v_id_produto INT;
    DECLARE v_nome VARCHAR(40);
    DECLARE v_preco DECIMAL(10,2);
    DECLARE v_estoque INT;
    DECLARE v_fim INT DEFAULT 0;

    DECLARE cursor_produtos CURSOR FOR
        SELECT id_produto, nome, preco, qtd_estoque
        FROM produto;

    DECLARE CONTINUE HANDLER FOR NOT FOUND
        SET v_fim = 1;

    OPEN cursor_produtos;

    loop_produtos: LOOP
        FETCH cursor_produtos INTO v_id_produto, v_nome, v_preco, v_estoque;

        IF v_fim = 1 THEN
            LEAVE loop_produtos;
        END IF;

        SELECT 
            v_id_produto AS id,
            v_nome       AS nome,
            v_preco      AS preco,
            v_estoque    AS estoque;
    END LOOP;

    CLOSE cursor_produtos;
END ;;
DELIMITER ;
