/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `relatorio_estoque`()
BEGIN
    DECLARE v_nome VARCHAR(40);
    DECLARE v_preco DECIMAL(10,2);
    DECLARE v_estoque INT;
    DECLARE v_valor_estoque DECIMAL(10,2);
    DECLARE v_total_geral DECIMAL(10,2) DEFAULT 0;
    DECLARE v_fim INT DEFAULT 0;

    DECLARE cursor_estoque CURSOR FOR
        SELECT nome, preco, qtd_estoque
        FROM produto;

    DECLARE CONTINUE HANDLER FOR NOT FOUND
        SET v_fim = 1;

    OPEN cursor_estoque;

    loop_estoque: LOOP
        FETCH cursor_estoque INTO v_nome, v_preco, v_estoque;

        IF v_fim = 1 THEN
            LEAVE loop_estoque;
        END IF;

        SET v_valor_estoque = v_preco * v_estoque;
        SET v_total_geral = v_total_geral + v_valor_estoque;

        SELECT 
            v_nome           AS nome_produto,
            v_preco          AS preco,
            v_estoque        AS estoque,
            v_valor_estoque  AS valor_estoque;

    END LOOP;

    CLOSE cursor_estoque;

    -- Exibe o total geral ao final
    SELECT CONCAT('VALOR TOTAL DO ESTOQUE: ', FORMAT(v_total_geral, 2)) AS resultado_final;

END ;;
DELIMITER ;
